package com.rationportal.controller; import com.rationportal.service.RationCardImportService; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.Map; @RestController @RequestMapping("/api/import") public class RationCardImportController { private final RationCardImportService service; public RationCardImportController(RationCardImportService service){this.service=service;} @PostMapping("/ration-cards") public ResponseEntity<?> importRationCards(@RequestParam("file") MultipartFile file){ try { int count=service.importCsv(file); return ResponseEntity.ok(Map.of("status","success","imported",count)); } catch(Exception e){ return ResponseEntity.badRequest().body(Map.of("status","error","message","CSV import failed")); } } }
